$run = 45
$runPad = "045"
$rrlPath = "RRL/RRL-45.txt"

# RRL fidelity
$rrlFidelity = "MISSING"
if (Test-Path $rrlPath) {
    $rrlBytes = (Get-Item $rrlPath).Length
    $rrlText  = Get-Content $rrlPath -Raw
    $hasUser      = $rrlText -match '"role"\s*:\s*"user"'
    $hasAssistant = $rrlText -match '"role"\s*:\s*"assistant"'
    if ($rrlBytes -ge 50000 -and $hasUser -and $hasAssistant) {
        $rrlFidelity = "REAL"
    } elseif ($rrlBytes -ge 100 -and ($hasUser -or $hasAssistant)) {
        $rrlFidelity = "HOLLOW"
    }
    Write-Host "RRL: $rrlBytes bytes | hasUser=$hasUser | hasAssistant=$hasAssistant"
} else {
    Write-Host "RRL: MISSING at $rrlPath"
}

# DNA fidelity
$dnaFidelity = "MISSING"
$dnaRunPath  = "CANON/SOUL/EXTRACT/dna-run45.json"
if (Test-Path $dnaRunPath) {
    try {
        $dnaRecords = Get-Content $dnaRunPath -Raw | ConvertFrom-Json
        $bpCount = ($dnaRecords | Where-Object { $_.type -eq "blueprint" }).Count
        if ($dnaRecords.Count -gt 0 -and $bpCount -gt 0) { $dnaFidelity = "REAL" }
        elseif ($dnaRecords.Count -gt 0) { $dnaFidelity = "HOLLOW" }
        Write-Host "DNA: $($dnaRecords.Count) records | $bpCount blueprints"
    } catch { $dnaFidelity = "MISSING"; Write-Host "DNA parse error" }
} else {
    Write-Host "DNA: MISSING at $dnaRunPath"
}

# Ledger count
$ledgerCount = (Get-ChildItem "CANON/HEAVY-LEDGER/" -Filter "HL-*.json" -ErrorAction SilentlyContinue | Measure-Object).Count
Write-Host "LEDGER: $ledgerCount files"

# STARMAP
$starmapFiles = if (Test-Path "CANON/STARMAP") { (Get-ChildItem "CANON/STARMAP" -Recurse -File).Count } else { 0 }
Write-Host "STARMAP: $starmapFiles files"

# SOULKEYS
$soykeyDir  = "CANON/SOUL-KEYWORDS"
$soykeyFiles = if (Test-Path $soykeyDir) { (Get-ChildItem $soykeyDir -Recurse -File).Count } else { 0 }
$idxPath = "$soykeyDir\inverted-index.json"
$soykeyFidelity = "MISSING"
if (Test-Path $idxPath) {
    try {
        $idx = Get-Content $idxPath -Raw | ConvertFrom-Json -AsHashtable
        if ($idx.Count -gt 0) { $soykeyFidelity = "REAL" }
    } catch { }
}
Write-Host "SOULKEYS: $soykeyFiles files | index fidelity=$soykeyFidelity"

# S2Pipeline
$pipelineFiles = (Get-ChildItem "CANON/PIPELINE/" -Recurse -File -ErrorAction SilentlyContinue | Measure-Object).Count
$s2Path = "CANON/PIPELINE/pipeline-run045.json"
$s2PathAlt = "CANON/PIPELINE/pipeline-run45.json"
$pipelineFidelity = "MISSING"
if (Test-Path $s2Path) { $pipelineFidelity = "REAL" }
elseif (Test-Path $s2PathAlt) { $pipelineFidelity = "REAL" }
Write-Host "PIPELINE: $pipelineFiles files | run45=$pipelineFidelity"

# Summary table
Write-Host ""
Write-Host "=== FIDELITY GATE ==="
$verdicts = @(
    @{ Name="RRL";        Verdict=$rrlFidelity }
    @{ Name="SOUL";       Verdict="SOUL_BREATHING" }
    @{ Name="DNA";        Verdict=$dnaFidelity }
    @{ Name="LEDGER";     Verdict=if($ledgerCount -gt 0){"REAL"}else{"MISSING"} }
    @{ Name="STARMAP";    Verdict=if($starmapFiles -gt 0){"REAL"}else{"MISSING"} }
    @{ Name="SOULKEYS";   Verdict=$soykeyFidelity }
    @{ Name="S2Pipeline"; Verdict=$pipelineFidelity }
)
foreach ($v in $verdicts) {
    $icon = switch ($v.Verdict) {
        "REAL"    { "[GREEN]" }
        "HOLLOW"  { "[YELLOW]" }
        "MISSING" { "[RED]" }
        default   { "[SOUL_BREATHING]" }
    }
    Write-Host "  $icon $($v.Name): $($v.Verdict)"
